 TestAccess::reset(s);TestAccess::hand(s,0,"JAIL_327");TestAccess::deck(s,0,{"POOL_LOW_A","POOL_LOW_B","POOL_HIGH","CORE_CS2_024"});s.apply_action(play(s));s.apply_action({ActionType::EndTurn});check(TestAccess::player(s,0).board.size()==1,"Reinforcement Aura summons an eligible deck minion");auto summoned=TestAccess::player(s,0).board[0].card_id;check(summoned=="POOL_LOW_A"||summoned=="POOL_LOW_B","summon filter uses minion cost at most two");check(TestAccess::player(s,0).deck.size()==3,"summon removes exactly the chosen candidate");
