void test_felscreamer_discount_persists_until_demon(){auto s=game();TestAccess::reset(s);TestAccess::hand(s,0,"CORE_BT_416");TestAccess::hand(s,0,"TEST_DEMON");TestAccess::hand(s,0,"TEST_FILLER");s.apply_action(play(s));s.apply_action({ActionType::EndTurn});s.apply_action({ActionType::EndTurn});auto acts=s.legal_actions();check(std::any_of(acts.begin(),acts.end(),[](const auto& a){return a.type==ActionType::PlayCard&&a.hand_index==1;}),"non-Demon can be played while discount waits");s.apply_action(play_hand(s,1));s.apply_action({ActionType::EndTurn});s.apply_action({ActionType::EndTurn});auto obs=s.observation(0);auto demon=std::find_if(obs.self_hand.begin(),obs.self_hand.end(),[](const auto& c){return c.card_id=="TEST_DEMON";});check(demon!=obs.self_hand.end()&&demon->current_cost==3,"discount survives multiple turns and unrelated card play");s.apply_action(play_hand(s,0));check(TestAccess::player(s,0).hand.empty(),"discounted Demon consumes the held discount");}
