 auto order=[](const GameSession& game){std::vector<std::string> rows;for(const auto& line:game.diagnostic_trace())if(line.starts_with("END_TURN_REACTION")||line.starts_with("SECRET_RESOLVE"))rows.push_back(line.starts_with("SECRET_RESOLVE")?"FLAMES":(rows.empty()?"A":"B"));return rows;};check(order(s)==std::vector<std::string>{"A","FLAMES","B"},"board source, later Flames, and later board source share activation order");check(order(*branch)==order(s),"clone preserves event sequence stamps and ordering");
