TestAccess::reset(s);TestAccess::secret(s,1,"TEST_EOT_SECRET_A");TestAccess::secret(s,1,"TEST_EOT_SECRET_B");auto activation=s.observation(1);check(activation.self_player.known_secrets==std::vector<std::string>{"TEST_EOT_SECRET_A","TEST_EOT_SECRET_B"},"owner sees active Secret identities in activation order");check(activation.self_player.secret_count==2,"owner observes active Secret count");auto hidden=s.observation(0);check(hidden.opponent.secret_count==2&&hidden.opponent.known_secrets.empty(),"opponent sees Secret count without identities");TestAccess::minion(s,0,"TEST_FILLER",1,2);TestAccess::minion(s,0,"TEST_FILLER",1,2);s.set_trace_enabled(true);s.apply_action(Action{ActionType::EndTurn});trace=s.diagnostic_trace();auto first=std::find_if(trace.begin(),trace.end(),[](const auto& x){return x.starts_with("SECRET_RESOLVE card=TEST_EOT_SECRET_A");});auto second=std::find_if(trace.begin(),trace.end(),[](const auto& x){return x.starts_with("SECRET_RESOLVE card=TEST_EOT_SECRET_B");});check(first<second,"two Secrets resolving in one window retain activation order");const auto consumed_sequence=TestAccess::next_sequence(s);TestAccess::secret(s,1,"TEST_EOT_SECRET_A");check(TestAccess::player(s,1).secrets.back().activation_sequence>=consumed_sequence,"a Secret re-entering the active zone gets a new sequence");
 TestAccess::reset(s);TestAccess::active(s,1);TestAccess::secret(s,0,"CORE_EX1_287");TestAccess::player(s,1).mana=10;TestAccess::hand(s,1,"CORE_CS2_029");auto spell=play(s,1);s.apply_action(spell);check(TestAccess::player(s,1).mana==6&&TestAccess::player(s,1).spells_cast_this_turn==1&&TestAccess::player(s,0).hero_health==30,"Counterspell runs after cost and cast history but cancels the spell effect");TestAccess::hand(s,1,"JAIL_321");s.apply_action(play_hand(s,0));check(TestAccess::player(s,1).spells_cast_this_turn==3&&TestAccess::player(s,1).secrets.size()>=1,"Tricksy uses generic cast history, full pool random casts, and counts both casts");
 TestAccess::reset(s);TestAccess::secret(s,1,"CORE_EX1_289");TestAccess::weapon(s,0,"CS2_106",3,2);s.apply_action(attack(s,1,2));check(TestAccess::player(s,1).armor==5&&TestAccess::player(s,1).hero_health==30,"Ice Barrier adds 8 armor after attack declaration, then combat damage consumes 3 armor");
 TestAccess::reset(s);TestAccess::secret(s,1,"CORE_BAR_812");int attacker=TestAccess::minion(s,0,"TEST_FILLER",1,2,true);int target=TestAccess::minion(s,1,"TEST_FILLER",1,3);bool unsupported=false;try{s.apply_action(attack(s,attacker,target));}catch(const UnsupportedSimulationError&){unsupported=true;}check(unsupported&&!s.is_valid(),"Oasis Ally fails closed on unimplemented Freeze dependency");
