void test_fail_closed_and_catalog_validation(){auto defs=catalog();auto unknown=def("TYPO","SPELL",1,0,0,"TYPO_ABILITY");defs.push_back(unknown);bool rejected=false;try{CardCatalog invalid(std::move(defs));}catch(const std::invalid_argument&){rejected=true;}check(rejected,"unknown ability fails catalog load");
 auto invalid_freeze=catalog();auto bad_freeze=def("BAD_FREEZE","SPELL",1,0,0,"EFFECT_COMPOSITION");bad_freeze.effects={effect(EffectKind::Freeze,TargetSelector::Self,0)};invalid_freeze.push_back(bad_freeze);rejected=false;try{CardCatalog invalid(std::move(invalid_freeze));}catch(const std::invalid_argument&){rejected=true;}check(rejected,"Freeze effect rejects non-character selectors");
 auto invalid_freeze_amount=catalog();bad_freeze=def("BAD_FREEZE_AMOUNT","SPELL",1,0,0,"EFFECT_COMPOSITION");bad_freeze.effects={effect(EffectKind::Freeze,TargetSelector::ExplicitCharacter,1)};invalid_freeze_amount.push_back(bad_freeze);rejected=false;try{CardCatalog invalid(std::move(invalid_freeze_amount));}catch(const std::invalid_argument&){rejected=true;}check(rejected,"Freeze effect rejects a nonzero amount");
 auto generated_catalog=catalog();auto bad=def("UNSUPPORTED_CARD","MINION",1,1,1,"NONE");bad.support_state="UNSUPPORTED";generated_catalog.push_back(bad);generated_catalog.push_back(def("GENERATES_UNKNOWN","SPELL",1,0,0,"MINION_DAMAGE_GENERATE",1,"UNSUPPORTED_CARD"));auto deck=std::vector<std::string>(30,"TEST_FILLER");GameSession s(deck,deck,std::move(generated_catalog),1,false,"MAGE","MAGE");TestAccess::reset(s);TestAccess::hand(s,0,"GENERATES_UNKNOWN");auto target=TestAccess::minion(s,1,"POOL_LOW_B",2,4);bool invalidated=false;try{s.apply_action(play(s,target));}catch(const UnsupportedSimulationError&){invalidated=!s.is_valid()&&s.unsupported_outcome().has_value();}check(invalidated,"unsupported generated result explicitly invalidates branch");
 TestAccess::reset(s);TestAccess::hand(s,0,"UNSUPPORTED_CARD");bool hand_rejected=false;try{(void)s.legal_actions();}catch(const UnsupportedSimulationError&){hand_rejected=true;}check(hand_rejected,"unsupported card in actionable hand fails closed");}
