 TestAccess::reset(s);TestAccess::player(s,0).hero_health=1;TestAccess::player(s,1).hero_health=1;
 TestAccess::minion(s,0,"CORE_EX1_012",1,1);TestAccess::minion(s,1,"CORE_EX1_012",1,1);TestAccess::set_health(s,0,0,0);TestAccess::set_health(s,1,0,0);TestAccess::stabilize(s);
 check(s.result()==std::optional<std::string>{"DRAW"},"fatigue from both deathrattles can cause a draw");
 TestAccess::reset(s);TestAccess::secret(s,1,"END_024");s.apply_action(Action{ActionType::EndTurn});
 check(TestAccess::player(s,1).secrets.size()==1,"Flames remains armed when no living minion is eligible");
 TestAccess::reset(s);TestAccess::minion(s,0,"CATA_475",3,6);TestAccess::minion(s,1,"CORE_EX1_012",1,1);
 TestAccess::minion(s,0,"CORE_EX1_012",1,1);TestAccess::set_health(s,0,1,0);
 TestAccess::queued_death_reaction(s,0);TestAccess::stabilize(s);
 check(TestAccess::player(s,1).board.empty()&&TestAccess::player(s,1).fatigue==1&&TestAccess::player(s,0).fatigue==1,"death-phase queued reaction creates a second death batch whose mandatory draw resolves");
 TestAccess::reset(s);TestAccess::hand(s,0,"CORE_EX1_145");TestAccess::enter(s,0,"CATA_489");TestAccess::player(s,0).hand[0].spell_damage_bonus=1;
 bool merge_blocked=false;try{s.apply_action(play_hand(s,1));}catch(const UnsupportedSimulationError&){merge_blocked=true;}
 check(merge_blocked&&!s.is_valid(),"modified Shatter fragments cannot silently sum unverified modifiers on recombination");
 auto invalid=catalog();auto freeze=def("UNMODELED_FREEZE","MINION",4,3,6);freeze.required_mechanics={"FREEZE"};invalid.push_back(freeze);
 bool rejected=false;try{CardCatalog ignored(std::move(invalid));}catch(const std::invalid_argument&){rejected=true;}
